-- Generated by scripts/build-ai-construction-evidence-catalog.ts.
-- Apply 20261027101807_construction_observations.sql, deploy compatible ask-bob
-- AND bob-worker, then activate. Old manifests retain their prior schemas/path.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $construction_evidence_publication$
declare specs jsonb:=$construction_evidence_spec$[{"key":"tools.check_construction_draft","patch":{"description":"Check an exact current saved construction before drawing. Reads canonical geometry and catalog revisions server-side. Supports uncut wooden boxes, right-angle rotations and planar screwed/glued butt-joint concepts. Reports collisions, wrong local faces, missing joints, disconnected parts and material dimension mismatches with stable IDs. Compare returned bounds/count against the original request. concept_ready permits concept development only; fabrication_ready is always false until product, hardware, load and manufacturing checks exist. Unsupported operations and stale sources stop this check. component_ids:[] checks the whole model; named concept IDs start a local scope that expands to dependencies, neighbors and joints. requirement_checks bind registered feature IDs to clear_space (a space/opening component), minimum_span (physical component, axis and positive minimum_node from the concept), or connected (mapped component_ids). Give each probe a stable id. The code reports actual properties and every unprobed/unsupported requirement, retaining unverified functional meaning. Both local and whole findings are saved for later turns; read them with view=results/result. A property pass does not prove the natural-language function or grant delivery.","parameters":{"type":"object","additionalProperties":false,"properties":{"artifact_id":{"type":"string","format":"uuid"},"revision":{"type":"integer","minimum":1,"maximum":999999999},"component_ids":{"type":"array","maxItems":48,"uniqueItems":true,"items":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"}},"requirement_checks":{"type":"array","maxItems":48,"items":{"anyOf":[{"type":"object","additionalProperties":false,"properties":{"id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"},"feature_id":{"type":"string","pattern":"^[A-Za-z0-9_-]{1,32}$"},"kind":{"type":"string","enum":["clear_space"]},"component_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"}},"required":["id","feature_id","kind","component_id"]},{"type":"object","additionalProperties":false,"properties":{"id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"},"feature_id":{"type":"string","pattern":"^[A-Za-z0-9_-]{1,32}$"},"kind":{"type":"string","enum":["minimum_span"]},"component_id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"},"axis":{"type":"string","enum":["x","y","z"]},"minimum_node":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"}},"required":["id","feature_id","kind","component_id","axis","minimum_node"]},{"type":"object","additionalProperties":false,"properties":{"id":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"},"feature_id":{"type":"string","pattern":"^[A-Za-z0-9_-]{1,32}$"},"kind":{"type":"string","enum":["connected"]},"component_ids":{"type":"array","minItems":2,"maxItems":12,"uniqueItems":true,"items":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_-]{0,31}$"}}},"required":["id","feature_id","kind","component_ids"]}]}}},"required":["artifact_id","revision","component_ids","requirement_checks"]},"required_parameters":["artifact_id","revision","component_ids","requirement_checks"]}},{"key":"tools.read_construction_draft","patch":{"description":"Read a small construction overview, then exact revision-bound pages. Default view=overview; artifact_id:null lists drafts. parts shows definitions and placements; parameters includes exact formulas, normalized values and source pins; dependencies follows named part/node dependencies, bindings, joints and roles. ids:[] reads the whole selected view; named IDs select matching records (dependencies also follows ancestors/dependents). notes contains original description/questions. Result references reopen an earlier check/list/cut assessment without rerunning it: view=result, exact artifact/revision/result_id, section:null for all or a returned section name, ids:[]. Historical results do not prove current sources or grant write/drawing permission. Follow next_read and coverage before relying on omitted details. Each page preserves exact posts; an oversized post is explicitly split into JSON fragments with offsets. Never reconstruct a full construction merely to inspect or change one part. view=results lists saved check references for this exact revision across turns; follow next_read. view=result reopens those findings. Source/checker changes keep history readable and prevent reuse as current evidence.","parameters":{"type":"object","additionalProperties":false,"properties":{"artifact_id":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"revision":{"anyOf":[{"type":"integer","minimum":1,"maximum":999999999},{"type":"null"}]},"after":{"anyOf":[{"type":"string","maxLength":240},{"type":"null"}]},"view":{"type":"string","enum":["overview","parts","parameters","bindings","joints","materials","roles","notes","dependencies","result","results"]},"ids":{"type":"array","maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":240}},"result_id":{"anyOf":[{"type":"string","pattern":"^cs_[a-f0-9]{64}$"},{"type":"null"}]},"section":{"anyOf":[{"type":"string","minLength":1,"maxLength":120},{"type":"null"}]}},"required":["artifact_id","revision","after","view","ids","result_id","section"]},"required_parameters":["artifact_id","revision","after","view","ids","result_id","section"]}}]$construction_evidence_spec$::jsonb;
 item jsonb; prior shared.ai_prompt_versions; next_version integer; version_uuid uuid; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for item in select value from jsonb_array_elements(specs) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
   where p.app='bob' and p.prompt_key=item->>'key' and p.retired_at is null for update of p;
  if not found then raise exception 'construction_evidence_contract_missing'; end if;
  if prior.metadata->>'construction_evidence_version'='1' then continue; end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,
    (prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','construction-evidence-v1','construction_evidence_version',1),
    prior.content,prior.definition||(item->'patch'),prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid);
 end loop;
 if activation<>'{}'::jsonb then perform shared.activate_ai_catalog('bob',activation); end if;
end $construction_evidence_publication$;
commit;
